-- Eleanor Evans (profileID=5) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Eleanor Evans phrasings

SELECT p.argumentID, p.phrasingID, 5, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 5
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 5 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=5 AND targArgID IN (100,101,105,107,108,123,124,125,126,136,140,142,143,161,165,166,175,224,226,229,230,288,291,297,298,321,322,328,349,350,400,401,405,406,407,414,428,460,462,476,546,560,561,574,596,600,601,607,611,612,616,617,777,785,790,791,793,795,797,801,821,844,849,902,903,920,1001,1159,1160,1172,1177,1178,1179,1181,1229,1237,1275,1276,1313,1319,1320,1345,1346,1347,1385,1386,1387,1410,1411,1438,1440,1562);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 5
SET pe.active = o.acceptance
WHERE pe.profileID = 5;

SELECT 'Done: endorsements for profileID=5' AS status;